css:
:root{
  --green-900:#14331f; --green-800:#1a4127; --green-700:#1f4d2e; --green-600:#2f7d4a; --green-500:#3a9d5f;
  --accent:#d98a3d; --accent-dark:#bd7328;
  --ink:#16241c; --body:#33413a; --muted:#6b7b72;
  --bg:#f6f8f4; --card:#ffffff; --line:#e3ebe3; --tint:#eef3ea;
  --gut:40px; --maxw:1200px;
  --shadow:0 18px 45px -22px rgba(20,51,31,.35);
  --shadow-sm:0 6px 20px -12px rgba(20,51,31,.35);
  --rad:16px;
  font-family:'Inter',system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--body);font-size:17px;line-height:1.7;-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block}
a{color:var(--green-600);text-decoration:none}
svg{width:18px;height:18px;flex-shrink:0}
h1,h2,h3,h4{font-family:'Plus Jakarta Sans',sans-serif;color:var(--ink);line-height:1.18;margin:0;font-weight:800;letter-spacing:-.01em}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 var(--gut)}
.rv{animation:rvIn .8s both}
@keyframes rvIn{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){.rv{animation:none}}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.5em;font-family:'Plus Jakarta Sans',sans-serif;font-weight:700;font-size:15px;padding:13px 22px;border-radius:999px;border:2px solid transparent;cursor:pointer;transition:transform .15s ease,box-shadow .15s ease,background .15s ease;white-space:nowrap}
.btn:hover{transform:translateY(-2px)}
.btn-accent{background:var(--accent);color:#3a2400;box-shadow:0 10px 22px -10px rgba(217,138,61,.8)}
.btn-accent:hover{background:var(--accent-dark)}
.btn-ghost{background:transparent;border-color:rgba(255,255,255,.5);color:#fff}
.btn-ghost:hover{background:rgba(255,255,255,.12)}
.hero{background:linear-gradient(180deg,var(--tint),var(--bg));border-bottom:1px solid var(--line)}
.hero .wrap{padding-top:36px;padding-bottom:40px}
.crumb{font-size:13.5px;color:var(--muted);display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:20px}
.crumb a{color:var(--muted)}
.crumb a:hover{color:var(--green-600)}
.crumb .sep{opacity:.5}
.pill{display:inline-flex;align-items:center;gap:8px;background:#fff;border:1px solid var(--line);color:var(--green-700);font-family:'Plus Jakarta Sans',sans-serif;font-weight:700;font-size:12.5px;letter-spacing:.06em;text-transform:uppercase;padding:7px 14px;border-radius:999px;box-shadow:var(--shadow-sm)}
.pill .lf{color:var(--accent-dark)}
h1.title{font-size:clamp(32px,5.4vw,52px);margin:18px 0 0;max-width:20ch}
h1.title .accent{color:var(--green-600)}
.lede{font-size:clamp(17px,2.2vw,20px);color:var(--body);max-width:64ch;margin:16px 0 0;line-height:1.6}
.listing{padding:48px 0 8px}
.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}
.card{position:relative;background:var(--card);border:1px solid var(--line);border-radius:var(--rad);overflow:hidden;box-shadow:var(--shadow-sm);display:flex;flex-direction:column;transition:transform .18s ease,box-shadow .18s ease}
.card:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.card .thumb-wrap{position:relative;background:#dfe7e0}
.card img.thumb{width:100%;aspect-ratio:16/9;object-fit:cover}
.card .cat{position:absolute;left:14px;top:14px;background:rgba(255,255,255,.94);color:var(--green-700);font-family:'Plus Jakarta Sans',sans-serif;font-weight:700;font-size:11.5px;letter-spacing:.06em;text-transform:uppercase;padding:6px 12px;border-radius:999px;box-shadow:var(--shadow-sm)}
.card .cbody{padding:22px 22px 20px;display:flex;flex-direction:column;flex:1}
.card h3{font-size:20px;line-height:1.28;margin:0 0 10px}
.card h3 a{color:var(--ink)}
.card h3 a::after{content:"";position:absolute;inset:0}
.card:hover h3 a{color:var(--green-700)}
.card .exc{font-size:15.5px;color:var(--body);margin:0 0 18px;flex:1}
.card .cfoot{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:auto;padding-top:14px;border-top:1px solid var(--line)}
.card .rt{display:inline-flex;align-items:center;gap:7px;font-size:13.5px;color:var(--muted)}
.card .more{display:inline-flex;align-items:center;gap:7px;font-family:'Plus Jakarta Sans',sans-serif;font-weight:700;font-size:14px;color:var(--green-600)}
.card .more svg{width:16px;height:16px}
@media(max-width:1024px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:640px){.grid{grid-template-columns:minmax(0,1fr)}}
.cta{background:radial-gradient(120% 140% at 12% 0%,var(--green-700),var(--green-900));color:#eaf3ec;margin-top:52px;position:relative;overflow:hidden}
.cta::after{content:"";position:absolute;right:-80px;top:-80px;width:320px;height:320px;border-radius:50%;background:radial-gradient(circle,rgba(217,138,61,.22),transparent 62%)}
.cta .wrap{padding-top:56px;padding-bottom:56px;position:relative;z-index:1}
.cta .pill{background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.22);color:#fff}
.cta h2{color:#fff;font-size:clamp(26px,4vw,38px);margin:16px 0 0;max-width:20ch}
.cta p{max-width:60ch;margin:16px 0 0;color:#cfe0d3;font-size:17px}
.cta .row{display:flex;flex-wrap:wrap;gap:14px;margin-top:26px}
.cta .chips{display:flex;flex-wrap:wrap;gap:10px 22px;margin-top:26px;font-size:14.5px;color:#dbe8de}
.cta .chips span{display:inline-flex;align-items:center;gap:8px}
.cta .chips svg{color:var(--accent)}
@media(max-width:768px){ :root{--gut:26px} }
@media(max-width:480px){ :root{--gut:20px} body{font-size:16px} }

/* centre-align hero + CTA */
.hero .wrap{text-align:center}
.hero .crumb{justify-content:center}
.hero h1.title{margin-left:auto;margin-right:auto}
.hero .lede{margin-left:auto;margin-right:auto}
.cta .wrap{text-align:center}
.cta h2{margin-left:auto;margin-right:auto}
.cta p{margin-left:auto;margin-right:auto}
.cta .row{justify-content:center}
.cta .chips{justify-content:center}
